baseCss:
.aha-numbers{
  container:aha-numbers / inline-size;
  --aha-numbers-surface:var(--aha-white);
  --aha-numbers-ink:var(--aha-text-default);
  --aha-numbers-ink-secondary:var(--aha-text-secondary);
  --aha-numbers-value:var(--aha-color-primary);
  --aha-numbers-eyebrow:var(--aha-color-primary);
  --aha-numbers-divider:var(--aha-border-default);
  background:var(--aha-numbers-surface);
  color:var(--aha-numbers-ink);
  font-family:var(--aha-font-product);
}
.aha-numbers *{box-sizing:border-box}
:where(.aha-numbers) :is(h2,h3,p,ul,ol,figure){margin:0;padding:0}
:where(.aha-numbers) :is(ul,ol){list-style:none}
.aha-numbers__inner{max-width:1280px;margin:0 auto;padding:var(--aha-space-96) var(--aha-space-64)}
.aha-numbers__header{max-width:720px;margin:0 0 var(--aha-space-64)}
.aha-numbers__header--center{margin-inline:auto;text-align:center}
.aha-numbers__eyebrow{
  margin:0 0 var(--aha-space-16);
  font-size:var(--aha-size-sm);
  font-weight:var(--aha-weight-semibold);
  letter-spacing:var(--aha-letter-spacing-subheadings);
  text-transform:uppercase;
  color:var(--aha-numbers-eyebrow);
}
.aha-numbers__title{
  margin:0 0 var(--aha-space-20);
  font-family:var(--aha-font-display);
  font-size:var(--aha-size-h2);
  line-height:var(--aha-line-height-tight);
  font-weight:var(--aha-weight-semibold);
  letter-spacing:var(--aha-letter-spacing-headlines);
  color:var(--aha-numbers-ink);
}
.aha-numbers__lead{
  max-width:44ch;
  font-size:clamp(var(--aha-size-l),1.4vw,var(--aha-size-xl));
  line-height:var(--aha-line-height-body);
  color:var(--aha-numbers-ink-secondary);
}
.aha-numbers__icon{
  display:flex;align-items:center;justify-content:center;flex:none;
  width:var(--aha-space-48);height:var(--aha-space-48);
  border-radius:var(--aha-radius-default);
  background:var(--aha-bg-accent);color:var(--aha-color-primary);
}
.aha-numbers__actions{display:flex;flex-wrap:wrap;gap:var(--aha-space-12);margin-top:var(--aha-space-16)}
.aha-numbers__button{
  display:inline-flex;
  align-items:center;
  justify-content:center;
  gap:var(--aha-space-8);
  min-height:var(--aha-control-height-button-xl);
  padding:0 var(--aha-space-28);
  border:1px solid transparent;
  border-radius:var(--aha-radius-pill);
  font-family:inherit;
  font-size:var(--aha-size-l);
  font-weight:var(--aha-weight-semibold);
  text-decoration:none;
  cursor:pointer;
  background:var(--aha-button-primary-bg);
  color:var(--aha-button-primary-text);
  transition:background-color var(--aha-motion-mid) var(--aha-ease-in-out),transform var(--aha-motion-fast) var(--aha-ease-out);
}
.aha-numbers__button:hover{background:var(--aha-button-primary-bg-hover)}
.aha-numbers__button:active{background:var(--aha-button-primary-bg-press);transform:translateY(1px)}
.aha-numbers__button:focus-visible{outline:var(--aha-space-2) solid var(--aha-focus);outline-offset:var(--aha-space-2)}
.aha-numbers__button--ghost{
  background:var(--aha-button-default-bg);
  color:var(--aha-button-default-text);
  border-color:var(--aha-button-default-border);
}
.aha-numbers__button--ghost:hover{background:var(--aha-button-default-bg-hover);border-color:var(--aha-button-default-border-hover)}
.aha-numbers__button--ghost:active{background:var(--aha-button-default-bg-hover);border-color:var(--aha-button-default-border-press)}
.aha-numbers__photo{
  display:flex;align-items:center;justify-content:center;
  width:100%;
  background:var(--aha-bg-container-secondary);
  border-radius:var(--aha-radius-marketing);
  color:var(--aha-icon-muted);
  overflow:hidden;
}
.aha-numbers__photo--4x3{aspect-ratio:4 / 3}
.aha-numbers__photo--16x9{aspect-ratio:16 / 9}
.aha-numbers__photo--3x4{aspect-ratio:3 / 4}
.aha-numbers__photo img{display:block;width:100%;height:100%;object-fit:cover}
.aha-numbers__stats{display:grid;gap:var(--aha-space-48) var(--aha-space-32)}
.aha-numbers__stat{display:flex;flex-direction:column;gap:var(--aha-space-12)}
.aha-numbers__value{
  font-family:var(--aha-font-display);
  font-size:clamp(var(--aha-size-h2),5vw,var(--aha-size-h1));
  font-weight:var(--aha-weight-semibold);
  line-height:var(--aha-line-height-tight);
  color:var(--aha-numbers-value);
}
.aha-numbers__stat-title{
  font-size:var(--aha-size-xl);
  font-weight:var(--aha-weight-semibold);
  line-height:var(--aha-line-height-heading);
  color:var(--aha-numbers-ink);
}
.aha-numbers__stat-text{
  font-size:var(--aha-size-l);
  line-height:var(--aha-line-height-body);
  color:var(--aha-numbers-ink-secondary);
}
.aha-numbers--brand{
  --aha-numbers-surface:var(--aha-vivid-pink-100);
  --aha-numbers-ink:var(--aha-text-inverse);
  --aha-numbers-ink-secondary:var(--aha-text-inverse);
  --aha-numbers-value:var(--aha-text-inverse);
  --aha-numbers-eyebrow:var(--aha-text-inverse);
  --aha-numbers-divider:var(--aha-text-inverse);
}
@container aha-numbers (max-width:991px){
  .aha-numbers__title{font-size:var(--aha-size-h3)}
}
@container aha-numbers (max-width:767px){
  .aha-numbers__inner{padding:var(--aha-space-48) var(--aha-space-24)}
}
@container aha-numbers (max-width:479px){
  .aha-numbers__inner{padding:var(--aha-space-32) var(--aha-space-16)}
  .aha-numbers__title{font-size:var(--aha-size-h4)}
}

layouts.css:
.aha-numbers--centred .aha-numbers__header{display:flex;flex-direction:column;align-items:center}
.aha-numbers--centred .aha-numbers__icon{margin-bottom:var(--aha-space-20)}
.aha-numbers--centred .aha-numbers__stats{grid-template-columns:repeat(3,minmax(0,1fr));gap:0;max-width:960px;margin:0 auto}
.aha-numbers--centred .aha-numbers__stat{align-items:center;text-align:center;padding:var(--aha-space-8) var(--aha-space-32)}
.aha-numbers--centred .aha-numbers__stat + .aha-numbers__stat{border-left:1px solid var(--aha-numbers-divider)}
@container aha-numbers (max-width:767px){
  .aha-numbers--centred .aha-numbers__stats{grid-template-columns:minmax(0,1fr);gap:var(--aha-space-32)}
  .aha-numbers--centred .aha-numbers__stat + .aha-numbers__stat{border-left:0;border-top:1px solid var(--aha-numbers-divider);padding-top:var(--aha-space-32)}
}
